	Blanks off	String asis;;;          Copyright Apple Computer, Inc. 1986-89;	  All rights reserved;	 Written by Dan Oliver;;          This module contains control	definition procedures that define;          title bar and info bar controls.;;; Files needed:;          WINDCTL.ASM;            WC.MACROS;; 10/28/88  Dan O.	Handle titles and color tables as pointers or handles.;; 02/16/89  Harry 	Window titles could appear pass the right side of the zoom box. ;                   The clip rect is now set to the left side of the zoom box or if ;                   no zoom box the right side of the control rect before the title ;                   is drawn. I also subtract a little slop so that the title does ;                   not end right at the edge of either the zoom box or right side of ;                   control rect. BRC #36699.;; 21-Sep-90  Dave Lyons;; Fixed window title clipping (see "bpl titleFits").  Now it doesn't draw the title; on the desktop if the window is too narrow.;; 27-Sep-90	Dave Lyons;; Changes for using Get640Colors instead of hard-coding our own solid-colors table.;; 14-Nov-90	Dave Lyons;; Fixed memory-trashing bug in unlockColor (the two words of the color table handle; were reversed, so we were turning off bit 15 of a semi-random location).; See separate fix in WDefProc.asm's own unlockColor subroutine.; (This bug means that Window Color Table Resources can't be used reliably in; System 5.0 through 5.0.3.);	INCLUDE 'ALL.MACROS'	include 'WindMgrEquates.asm';===============================================================;          Control DefProc Equates;===============================================================;;; --- DefProc direct page offsets ----------------------------;ctlWind	equ 1	Pointer to window controls on.globals	equ ctlWind+4	Pointer to Window Manager globals.colors	equ globals+4	Pointer to window's color table.rgnSize	equ colors+4	To make 'rect' look	like a region.cRect	equ rgnSize+2	General RECT area.ctlPtr	equ cRect+8	Pointer to locked control.cWork	equ ctlPtr+4	cWork space.DIRECTSIZE	equ cWork+10	Size of allocated direct page.saveDpage	equ DIRECTSIZE+1	Caller's direct page.returnAddr	equ saveDpage+2	Long return addresses.ctlHand	equ returnAddr+3	Handle of control.cParam	equ ctlHand+4	Parameter defined by defProc operation.operation	equ cParam+4	DefProc operation to perform.result	equ operation+2	Result defined by defProc operation.;;;;; --- Document window record offsets -------------------------;wtitle	equ 212	Pointer to window's title.wtitle_w	equ wtitle+4	Width of title in pixels.worgn_mask	equ wtitle_w+2	Mask for horizontal	origin.wfull	equ worgn_mask+2	Size of window, used with ZoomWindow.wcolor	equ wfull+8	Pointer to window's color table.y_origin	equ wcolor+4	Content's vertical offset.x_origin	equ y_origin+2	Content's horizontal offset.data_h	equ x_origin+2	Height of total data area.data_w	equ data_h+2	Width of total data	area.wmaxheight	equ data_w+2	Maximum height for grow window.wmaxwidth	equ wmaxheight+2	Maximum width for grow window.vscroll	equ wmaxwidth+2	Amount to scroll vertically (arrows).hscroll	equ vscroll+2	Amount to scroll horizonally (arrows).vpage	equ hscroll+2	Amount to page vertically (page region).hpage	equ vpage+2	Amount to page horizontally (page rgn).wInfoRef	equ hpage+2	Value passed to Draw Info routine.wInfoHeight	equ wInfoRef+4	Height of information bar.woldYOrg	equ wInfoHeight+2	Save y origin on full window.woldXOrg	equ woldYOrg+2	Save x origin on full window.wInfoDraw	equ woldXOrg+2	Address of routine to draw Info Bar.DOCSIZE	equ wInfoDraw+4	!!! Change 'port' size in WDATA.ASM !!!;;; --- Window color table offsets -----------------------------;FRAME_CLR	equ 0	Frame's outline.TITLE_CLR	equ FRAME_CLR+2	Title's color.BAR_CLR	equ TITLE_CLR+2	Title bar's initerior.GROW_CLR	equ BAR_CLR+2	Grow box interior.INFOR_CLR	equ GROW_CLR+2	Information bar interior.COLORSIZ	equ INFOR_CLR+2	Size of color table.;;; --- Window DefProc frame offsets -----------------------------;TITLEH	equ 13	Height of title bar.TITLEL	equ 2	Space on left and right of title bar pattern.TITLET	equ 3	Space on top and bottom of title bar pattern.;CLOSEL	equ 10	Left side of window	to left side of close box.CLOSET	equ 2	Top of window to top of close box.CLOSEW	equ 22	Width of close box.CLOSEH	equ 11	Height of close box.;;;; --- GraphPort record offsets -------------------------------;boundsRect	equ $0008clipRgn	equ $0018visRgn	equ $001C;;; --- Control defProc operation numbers	----------------------;drawCntl	equ 0	Draw the control.calcCRect	equ drawCntl+1	Compute the drag RECT.testCntl	equ calcCRect+1	Perform a hit test on the control.initCntl	equ testCntl+1	Perform additional initialization.dispCntl	equ initCntl+1	Perform additional disposal.posCntl	equ dispCntl+1	Called when dragging complete with delta.thumbCntl	equ posCntl+1	Setup for dragging.dragCntl	equ thumbCntl+1	Perform dragging.autoTrack	equ dragCntl+1	Called while dragging.newValue	equ autoTrack+1	Called when new value is set.setParams	equ newValue+1	Called when min and	max are set.moveCntl	equ setParams+1	Move entire control.recSize	equ moveCntl+1	Return size of control's record.;titlePart	equ 16closePart	equ 17zoomPart	equ 18infoPart	equ 19;;; --- CtlFlags for title bar control -------------------------;closeCtl	equ $0040	1 = title bar has close box.zoomCtl	equ $0001	1 = title bar has zoom box.;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT Fill	IMPORT Print	IMPORT Restore	IMPORT Return	IMPORT Save	IMPORT Set	IMPORT Switch	IMPORT longCall	IMPORT pushDpage;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY pushWindTitle	ENTRY unlockTitle***	ENTRY colorBlack	ENTRY defRefCtl	ENTRY drawInfo	ENTRY drawTitle	ENTRY fillFrameRect	ENTRY getCloseCor	ENTRY getColorTable	ENTRY unlockColor	ENTRY getCoords	ENTRY getCtlRect	ENTRY getLineSize	ENTRY getWindPtr	ENTRY initTitle	ENTRY nullHandler	ENTRY pushLineSize	ENTRY pushRect	ENTRY set_patt	ENTRY shutdown	ENTRY smear	ENTRY startup	ENTRY testInfo	ENTRY testTitle	ENTRY titleRecSize	ENTRY titleValue;;;===============================================================;          Title bar custom control defProc.;===============================================================;;   IN:    PUSH:LONG - space for result.;          PUSH:WORD - operation to perform.;          PUSH:LONG - additional parameter defined by operation.;          PUSH:LONG - handle of control.;	EXPORT titleBarDefProctitleBarDefProc	PROC;;;	jsr startup	Allocate direct page.;	stz <result	Initialize result to null.	stz <result+2;	lda <operation	cmp #recSize+1	bcs shutdown	asl a	tax	jsr (tHandlers,x);;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;       Cleanup and	exit control defProc.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;	ENTRY shutdownshutdown		;       ;	lda <returnAddr+1	Move return address	over inputs.	sta <result-2	lda <returnAddr	sta <result-3;	ldx <saveDpage	Get original direct	page.;	tsc	Free allocated direct page and inputs.	clc	adc #result-4	tcs;	txa	Restore caller's direct page.	tcd	rtl	Return to defProc caller.;;tHandlers	DC.W drawTitle	0 drawCtl	DC.W nullHandler	1 calcCRect	DC.W testTitle	2 testCtl	DC.W initTitle	3 initCtl	DC.W nullHandler	4 dispCtl	DC.W nullHandler	5 posCtl	DC.W nullHandler	6 thumbCtl	DC.W nullHandler	7 dragCtl	DC.W nullHandler	8 autoTrack	DC.W titleValue	9 newValue	DC.W nullHandler	A setParams	DC.W nullHandler	B moveCtl	DC.W titleRecSize	C recSize;	ENDP;;;===============================================================;          Operation: drawCtl;===============================================================;;   IN:    <cParam =	part code to draw, zero if whole control.;drawTitle	PROC;		;using equates;flags	equ cWorkminX	equ flags+2active	equ minX+2iconNumber	equ active+2;;	jsr defRefCtl	<ctlPtr = pointer to control record.	jsr getCtlRect	<cRect = control's bounds.	jsr getWindPtr	<ctlWind = pointer to window.	jsr getColorTable	<colors = pointer to color table.;	ldy #wFrame	Active state of controls same as	lda [<ctlWind],y	window's state.	and #F_HILITED	TRUE = frame is highlighted.	sta <active;;; --- Set colors ---------------------------------------------;	ldy #ctlFlag	lda [<ctlPtr],y	sta <flags;	pea 4	Smear text colors.	_SetFontFlags;	ldy #TITLE_CLR	Inactive title bar color.	lda [<colors],y	xba	ldx <active	Is control active?	beq ok2	ldy #BAR_CLR	Lay down title bar background	lda [<colors],y	for an active window.ok2	jsr smear	Smear color into all 4 nibbles.	pha	Save background color.;	pha	Pass color of text's background.	_SetBackColor	Set title, close, zoom background color.;;	ldy #TITLE_CLR	Set color of text	lda [<colors],y	ldx <active	Is control active?	bne ok3	lsr a	Get its inactive color.	lsr a	lsr a	lsr aok3	jsr smear	Smear color into all 4 nibbles.	pha	_SetForeColor	Set color of text.;;;---------------------------------------------------;          Fill and	frame title bar.;---------------------------------------------------;	pea 0	Set text mode to copy.	_SetTextMode;	pla	Restore background color.	ldy <cParam	Whole control?	beq @DrawWhole	brl drawClose;@DrawWhole	and #$00F0	Put color into proper nibble for fill.	pha	Save fill color.;	ldy #FRAME_CLR	Pass outline color.	lda [<colors],y	and #$00F0	ply	Pass fill color.	jsr fillFrameRect	Draw blank title bar.;;	lda <active	If title bar is inactive don't fill	beq printTitle	with active pattern.;	ldy #BAR_CLR	Get title bar pattern.	lda [<colors],y	and #$FF00	Solid pattern?	beq printTitle	If solid, no foreground to fill.;	jsr pushRect	Indent cRECT for pattern fill.	jsr getLineSize	a = width of lines,	x = height of lines.	asl a	inx	pha	Pass width.	phx	Pass height.	_InsetRect;	jsr pushRect	Pass address of 'cRect'.	ldy #BAR_CLR	Get title bar pattern.	lda [<colors],y	tay	jsr set_patt	Generate pattern.	phx	Pass pointer to pattern.	phy	_FillRect	Fill with highlight	pattern.;	jsr getCtlRect	<cRect = control's bounds.;;; ------- Print title in title bar -----------------------; ;  IN: <cRect = control's bounds;      <ctlPtr = ptr to title's control record; OUT: <cRect = trashed;printTitle	jsr defRefCtl	<ctlPtr = pointer to control record.;	lda <flags	Check if there is a zoom box	and #zoomctl	beq NoZoom		ldx #2	There is a zoom box, so get the coordinates for it	jsr (getcoords,x)	Coordinates are put into <cRect	lda <cRect+x1	We just need left side	pha	jsr getCtlRect	<cRect = control's bounds	pla	bra storeit	NoZoom	lda <cRect+x2	Compute right side of titlestoreit	sec	sbc #8	Subtract a little slop	sta <cRect+x2		ldy #ctlValue	lda [<ctlPtr],y	Get left side of title	sta <cRect+x1		lda <cRect+x2	sec	sbc <cRect+x1	ldy #wtitle_w	cmp [<ctlwind],y***	bcs TitleFits	bpl TitleFits	;21-Sep-90 DAL (window title clipping)		jsr MakeTitleFit	a-reg = space we have to work with	pea $0000	Flag for DrawString that says orig title has been chopped	bra aroundTitleFits	pea $FFFF	Flag for DrawString to tell us to use original titlearound	ldy #ctlValue	Pass x position.	lda [<ctlPtr],y	pha	ldy #titleYPos	Pass y position.	lda [<globals],y	pha	_MoveTo	Set pen's starting position.	jsr defRefCtl	<ctlPtr = pointer to control record.	pla	bmi TitleGood	lda <globals	ldx <globals+2	clc	adc #WindTitle	bcc @noCarry	inx@noCarry	phx	pha	bra drawit	TitleGood	jsr pushWindTitle	Pass pointer to window's title.drawit	_DrawString	Print window's title.		jsr unlockTitle	Leave title unlocked.;;-------------------------------------;          Draw close box.;-------------------------------------;drawClose	lda <active	If title bar is inactive then done.	beq exit;	jsr defRefCtl	<ctlPtr = pointer to control record.;	ldy #ctlHilite	Set hilite flag.	lda [<ctlPtr],y	and #$00FF	sta <cParam+2;	lda <cParam	Draw whole control?	beq ok5	cmp #closePart	Draw just the close	box?	bne drawZoom;ok5	lda <flags	and #closeCtl	Is there a close box?	beq drawZoom;	lda #0	Draw close box.	jsr drawBox	jsr defRefCtl	<ctlPtr = pointer to control record.;;;-------------------------------------;          Draw zoom box.;-------------------------------------;drawZoom	lda <cParam	Draw entire window?	beq ok4	cmp #zoomPart	Draw just the close	box?	bne exit;ok4	lda <flags	and #zoomCtl	Is there a zoom box?	beq exit;	lda #2	Draw zoom box.	jsr drawBox;;exit	pea 0	Restore to normal.	_SetFontFlags;	jsr unlockColor	Leave color table unlocked.;	ENTRY nullHandlernullHandler		;       	rts	;===============================================================;           	MakeTitleFit;===============================================================;;   IN:    a-reg	= amount of space we actually have to work with;;  OUT:    #windTitle offset from globals data area contains new window title	ENTRY MakeTitleFitMakeTitleFit		DefineStackOrigD	wordCount	wordNextCharSize	wordDestTitle	longOrigTitle	longTotalSpace	word	pha	Space we have to work with (TotalSpace)	jsr pushWindTitle	Get pointer to window title	lda <globals	Get pointer to where new and improved title will go	ldx <globals+2	(space for this is on the window mgr's global data area)	clc	adc #WindTitle	bcc @Skip	inx@Skip	phx		pha	pha	Space to hold next character in title	pha	Counter	phd	Save original direct page		tsc	Turn stack into direct page	tcd	;; --- Subtract width of elipsis and space character from total width -------------------;	lda #$20C9		sta <NextCharSize		pea 0	Space for result	pea 0	Pointer to text	tdc	clc	adc #NextCharSize	pha	pea 2	length of string	_TextWidth	lda <TotalSpace	sec	sbc 1,s	sta <TotalSpace	pla	Get length off of stack		stz <count	lop1	ldy <count	iny	Bump <count and get size of next character	lda [<OrigTitle],y	and #$00FF	pha	Save next char in window title on stack	pha	Space for result	pha	Character that we want width for	_CharWidth	pla	sta <NextCharSize	lda <TotalSpace	Subtract nextchar from total width we have to fit title in	sec	sbc <NextCharSize	bpl KeepInserting	Can't fit any more characters	pla	Clean up stack first	bra doneInsertingKeepInserting	sta <TotalSpace	inc <count	ldy <count	pla	Get next char off stack	sta [<DestTitle],y	bra lop1	doneInserting	lda #$20C9	Add '...' character to end of window's title	ldy <count	iny	sta [<DestTitle],y	iny	sty <count		lda [<OrigTitle]	Store new length of title	and #$FF00	ora <count	'OR' count in	sta [<DestTitle]		pld	Restore our stack.	tsc	clc	adc #14	tcs			rts; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;          Draw close or zoom box.;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;;   IN:    cParam+2 = FALSE if normal, TRUE if selected.;          a = 0 draw close box, 2 draw	zoom box.;;          Icon numbers are:  0 = normal close box.;	          1 = selected close or zoom box.;	          2 = normal zoom box.;;  OUT:    <cRect = trash.;drawBox	tax	Save box kind.	ldy <cParam+2	beq store100	If normal, use icon	number.	lda #1	Use selected icon.store100	sta <iconNumber	Save icon number.;;; --- Get coordinates of box ---------------------------------;	jsr (getCoords,x)	x = 0 if close box,	2 if zoom.;;; --- Draw the box -------------------------------------------;	pha	pha	_GetFontID	Save current font ID.	pha	pha	_GetFont	Save current font.;	ldy #windIconFont+2	Pass address of font pointer (handle).	lda [<globals],y	pha	dey	dey	lda [<globals],y	pha	_SetFont	Switch to icon font.;	pei <cRect+x1	Move pen to where icon should be.	pei <cRect+y1	_MoveTo;	pei <iconNumber	Pass character to print.	_DrawChar	Print icon.;	_SetFont	Restore original font.	_SetFontID	Restore orginal font ID.	rts;	ENDP;;;===============================================================;          Operation: initCtl;===============================================================;;   IN:    wtitle_w	= width of title string.;;  OUT:    ctlValue	= x position of title.;*initTitle  PRIVATEinitTitle	PROC;		;using equates;minX	equ cWork	ENTRY titleValuetitleValue	jsr defRefCtl	<ctlPtr = pointer to control record.	jsr getWindPtr	<ctlWind = pointer to window.;;; --- Set ctlValue field -------------------------------------;	stz <cRect+x2	Use left side of window if no close box.	ldy #ctlFlag	Is there a close box?	lda [<ctlPtr],y	and #closeCtl	beq skip1	jsr getCloseCor	Use right side of close box.skip1	lda <cRect+x2	Compute minimum x1 position of title.	clc	adc #8	sta <minX	jsr getCtlRect	<cRect = control's bounds.	lda <cRect+x2	Compute width of title bar.	sec	sbc <cRect+x1	ldy #wtitle_w	Subtract width of title.	sbc [<ctlWind],y	bcc tooBig	Title won't fit?	lsr a	Center the title.	cmp <minX	To the left of the close box?	bcs store1tooBig	lda <minX	Use minimum x position.store1	ldy #ctlValue	Store x position in	ctlValue.	sta [<ctlPtr],y	rts	ENDP;===============================================================;          Operation: testCtl;===============================================================testTitle	PROCboxNumber	equ cWork	jsr defRefCtl	<ctlPtr = pointer to control record.	jsr getWindPtr	<ctlWind = pointer to window.	lda #titlePart	Return title bar part code, just in case.	sta <result	ldy #wFrame	Is the title bar active?	lda [<ctlWind],y	and #F_HILITED	beq exit;; --- Check for hit	on close box --------------------------------;	ldy #ctlFlag	lda [<ctlPtr],y	and #closeCtl	Is there a close box?	beq ckZoom;	ldx #0	Check if point in close box.	jsr checkBox	beq ckZoom	Inside?;	lda #closePart	Return close box part code.	sta <result	rts;;; --- Check for hit	on zoom box --------------------------------;ckZoom	ldy #ctlFlag	lda [<ctlPtr],y	and #zoomCtl	Is there a zoom box?	beq exit;	ldx #2	Check if point in zoom box.	jsr checkBox	beq exit	Inside?;	lda #zoomPart	Return zoom box part code.	sta <resultexit	rts; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;          Check if	point in box.;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;;   IN:    x = 0 to	check close box, 2 to check zoom box.;          <cParam =	point to check.;;  OUT:    BEQ if point not in box.;checkBox	jsr (getCoords,x)	x = 0 if close box,	2 if zoom.	pha	Space for return value.	lda #cParam	Pass pointer to point to check.	jsr pushDpage	jsr pushRect	Pass RECT to check.	_PtInRect	pla	rts	ENDP;===============================================================;          Operation: recSize;===============================================================;titleRecSize	PROC	lda #ctlRecSize	Return size of standard control record.	sta <result	rts	ENDP;===============================================================;          Info bar	custom control defProc.;===============================================================;;   IN:    PUSH:LONG - space for result.;          PUSH:WORD - operation to perform.;          PUSH:LONG - additional parameter defined by operation.;          PUSH:LONG - handle of control.;	EXPORT infoBarDefProcinfoBarDefProc	PROC	jsr startup	Allocate direct page.	stz <result	Initialize result to null.	stz <result+2	lda <operation	Is operation in range?	cmp #recSize+1	bcs exit	asl a	tax	jsr (iHandlers,x)exit	brl shutdowniHandlers	DC.W drawInfo	drawCtl	DC.W nullHandler	calcCRect	DC.W testInfo	testCtl	DC.W nullHandler	initCtl	DC.W nullHandler	dispCtl	DC.W nullHandler	posCtl	DC.W nullHandler	thumbCtl	DC.W nullHandler	dragCtl	DC.W nullHandler	autoTrack	DC.W nullHandler	newValue	DC.W nullHandler	setParams	DC.W nullHandler	moveCtl	DC.W titleRecSize	C recSize	ENDP;====================================;          Draw info bar.;====================================;drawInfo	PROC;;portPtr	equ cWorkdummyHand	equ portPtr+4;;	jsr defRefCtl	<ctlPtr = pointer to control record.	jsr getCtlRect	<cRect = control's bounds.	jsr getWindPtr	<ctlWind = pointer to window.	jsr getColorTable	<colors = pointer to color table.;	ldy #INFOR_CLR	Information bar pattern.	lda [<colors],y	and #$00F0	Force solid.	pha	Save fill color.;	ldy #FRAME_CLR	Pass outline color.	lda [<colors],y	and #$00F0	ply	Pass fill color.	jsr fillFrameRect	Fill and frame 'rect'.;	jsr pushRect	jsr pushLineSize	Push size of lines.	_InsetRect;	jsr defRefCtl	<ctlPtr = pointer to control record.	ldy #ctlOwner	Get pointer to owner window.	lda [<ctlPtr],y	sta <portPtr	iny	iny	lda [<ctlPtr],y	sta <portPtr+2;	ldy #wPort+clipRgn+2 Save window's clip region handle.	lda [<portPtr],y	pha	lda #0	Replace with my dummy handle.	sta [<portPtr],y	dey	dey	lda [<portPtr],y	pha	tdc	clc	adc #dummyHand	sta [<portPtr],y;	lda #10	Make <rect look like a region.	sta <rgnSize;	tdc	Compute pointer to dummy region.	clc	adc #rgnSize	sta <dummyHand	Make dummy region handle.	stz <dummyHand+2;;	jsr pushRect	Pass information bar RECT.;	ldy #wInfoRef+2	Pass value in wInfoRef.	lda [<ctlWind],y	pha	dey	dey	lda [<ctlWind],y	pha;	ldx <ctlWind+2	Pass pointer to window port.	lda <ctlWind	clc	adc #4	bcc store1	inxstore1	phx	pha;	ldy #wInfoDraw+1	lda [<ctlWind],y	tax	dey	lda [<ctlWind],y	jsl longCall	Call draw routine.;	ldy #wPort+clipRgn	Retore clip handle.	pla	sta [<portPtr],y	iny	iny	pla	sta [<portPtr],y;	jsr unlockColor	Leave color table unlocked.	clc	No error flag.	rts	ENDP;;;===============================================================;          Operation: testCtl;===============================================================;testInfo	PROC;;	lda #infoPart	Return info bar part code.	sta <result	rts	ENDP;;;===============================================================;          Allocate	a direct page for the control defProc.;===============================================================;startup	PROC;		;using equates;;; --- Allocate a stack based direct page -----------------------;	plx	Get return address.;	phd	Save original direct page.;	tsc	Allocate a stack based direct page.	sec	sbc #saveDpage-1	tcs	tcd;	phx	Put return address back.;	pha	pha	_GetWindowMgrGlobals	pla	sta <globals	pla	sta <globals+2;	rts	ENDP;;;===============================================================;          Dereference the control handle.;===============================================================;defRefCtl	PROC;		;using equates;;	ldy #2	Dereference the handle.	lda [<ctlHand],y	sta <ctlPtr+2	lda [<ctlHand]	sta <ctlPtr	rts	ENDP;;;===============================================================;          Clone control's bounds RECT.;===============================================================;;   IN:    <ctlPtr = pointer to control	record.;;  OUT:    <cRect = clone of control's ctlRect field.;*getCtlRect PRIVATEgetCtlRect	PROC;		;using equates;;	ldy #ctlRect+x2	ldx #x2lop1	lda [<ctlPtr],y	sta <cRect,x	dey	dey	dex	dex	bpl lop1	rts	ENDP;;;===============================================================;          Set color table pointer.;===============================================================;;   IN:    <ctlWind = pointer to window.;          <globals	= pointer to Window	Manager globals.;;  OUT:    <colors = pointer to control's color table.;getColorTable	PROC;	ldy #wcolor	Fetch color table field from window record.	lda [<ctlWind],y	tax	iny	iny	lda [<ctlWind],y	bmi @handle	Is the color table a handle?	bne @store1	Is the color table a pointer?	txy	bne @store1;;; --- NIL color table, use default.;	ldy #defWindClr	Use default color table.	lda [<globals],y	tax	iny	iny	lda [<globals],y	bpl @store1	Is default a pointer?;;; --- Handle for color table.;@handle	stx <colors	Store handle.	sta <colors+2;	ldy #4	Lock the color table.	lda [<colors],y	ora #$8000	sta [<colors],y	dey	Dereference the color table.	dey	lda [<colors],y	pha	lda [<colors]	tax	pla;@store1	stx <colors	sta <colors+2;	rts	ENDP;;;;====================================================;          Unlock window's color table.;====================================================;;   IN:    <ctlWind = pointer to window.;;  OUT:    Color table unlocked if it is a handle.  This includes the default table.;unlockColor	PROC;	ldy #wcolor	Fetch color table field from window record.	lda [<ctlWind],y	tax	iny	iny	lda [<ctlWind],y	bmi @handle	Is the color table a handle?	bne @exit	Is the color table a pointer?	txy	bne @exit	If a pointer, nothing to unclock.;;; --- NIL color table, unlock default.;	ldy #defWindClr	Use default color table.	lda [<globals],y	tax	iny	iny	lda [<globals],y	bpl @exit	Is default a pointer?  If yes, nothing to unlock.;;; --- Handle for color table.;@handle	pei <cWork+2	Save.	pei <cWork;*****	sta <cWork	Store handle.	*****  This is how it is in ROM 3 --DAL 14-Nov-90*****	stx <cWork+2		*****  The two words are interchanged.	sta <cWork+2	;fixed 14-Nov-90 DAL for TOOL014	stx <cWork	;fixed 14-Nov-90 DAL for TOOL014;	ldy #4	Unlock the color table.	lda [<cWork],y	and #$7FFF	sta [<cWork],y;	pla	Restore.	sta <cWork	pla	sta <cWork+2;@exit	rts	ENDP;;;===============================================================;          Fill and	frame <cRect.;===============================================================;;   IN:    <cRect = RECT to frame and fill.;          a = bits	4-7 = frame color, others bits are zero.;          y = pattern type in high byte,;              pattern color number in high nybble of low byte,;              background color in low nibble of low byte.;*fillFrameRect PRIVATEfillFrameRect	PROC;		;using equates;fillPatt	equ 1framePatt	equ fillPatt+2;;	pha	Save frame pattern.	phy	Save fill pattern.;	tya	Fill with solid color?	and #$FF00	bne enter1	Can't do special if pattern fill.;;; --- Special case fill and frame in one call ----------------;	jsr pushRect	Pass address of 'rect'.	lda framePatt+4,s	jsr pushSmear	Push smeared color.	lda fillPatt+6,s	jsr pushSmear	Push smeared color.	_SpecialRect	bcc exit	Error?;	pla	Remove inputs to SpecialRect.	pla	pla	pla;;; --- Draw box with	fill pattern -----------------------------;enter1	lda framePatt,s	tay	jsr set_patt	Compute pointer to pattern.	phx	Pass address of pattern.	phy	_SetPenPat	Set color of frame outline.;	jsr pushRect	Pass address of 'rect'.	lda fillPatt+4,s	tay	jsr set_patt	phx	Pass address of pattern.	phy	_FillRect;	jsr pushRect	Pass address of 'rect'.	_FrameRect;exit	ply	Take fill pattern off stack.	pla	Take frame pattern off stack.	rts;;; = = = = = = = = =	= = = = = = = = = =;          Push smeared color.;100= = = = = = = =	= = = = = = = = = =;;   IN:    a = color in bits 4-7.;;  OUT:    Color smeared into all 4 nibbles and pushed on stack.;pushSmear	plx	Get return address.;	and #$00F0	pha	lsr a	lsr a	lsr a	lsr a	ora 1,s	sta 1,s	xba	ora 1,s	sta 1,s;	phx	Put return address back.	rts	ENDP;;;===============================================================;          Smear a mono bit image into color.;===============================================================;;  IN:     y = pattern type in high byte,;          pattern color number in high	nybble of low byte,;          background color in low nibble of low byte.;; OUT:     x = high	word address of pattern.;          y = low word address of pattern.;*set_patt   PRIVATEset_patt	PROC;		;using equates;;	lda <globals	ldx <globals+2	ENDP;;;   IN:    x/a = pointer to Window Manager's global data area.;	EXPORT makePatternmakePattern	PROC;		;using equates;dataArea	equ 1;;	phd	Save caller's direct page pointer.;	phx	Save pointer to data area.	pha;	tsc	Switch direct page into stack.	tcd;;; --- Solid color --------------------------------------------;	tya	Special case, solid	pattern.	and #$FF00	bne buildPatt;	tya	and #$00F0	asl a	clc***	adc #colorBlack	export SelfMod1LowSelfMod1Low	adc #$7777	;low word of 640Colors 27-Sep-90 DAL	tay***	ldx #colorBlack>>16	export SelfMod1HighSelfMod1High	ldx #$7777	;high word of 640Colors 27-Sep-90 DAL	brl exit;;; --- Fill pattern buffer with pattern color ----------.buildPatt	tya	Get pattern color.	lsr a	lsr a	lsr a	lsr a	jsr getcolor	Get color of next to lowest nibble.;	pha	Save color of pattern.	tya	jsr getcolor	Get color of background in low nibble.	pha	Save color of background.;	cpy #$0200	Lined or Dither pattern?	bcs enter1	If lined, then ready.;;; --- Special dither pattern -------------------------------------------;	tay	Save background color.	and #$F0F0	Dither the background color,	sta 1,s	save dither,	lda 3,s	get foreground color,	and #$0F0F	dither the foreground color.	ora 1,s	add background color,	sta 1,s	to get background dithered color.;	lda 3,s	Get foreground color,	and #$F0F0	dither it,	sta 3,s	save it.	tya	Get original background color,	and #$0F0F	dither it,	ora 3,s	and the foreground dithered color,	sta 3,s	to get foreground dithered color.;;;  On stack:     3 foreground color.;                1 background color.;;enter1	ldx #pattern+14	16 bytes if 640 mode.	ldy #screenMode	lda [<dataArea],y	Get current mode.	bne ok1	Which mode are we in?	ldx #pattern+30	32 bytes if 320 mode.ok1	txy	y = index into pattern buffer.	tax	x = mode, FALSE if 320, TRUE if 640.;lop3	jsr setFore	Store a WORD of foreground color.	txa	Which mode?	bne skip1	jsr setFore	If 320 store 2 words of foreground.;skip1	jsr setBack	Store a WORD of background color.	bcc done	Buffer full?	txa	Which mode?	bne lop3	jsr setBack	If 320 store 2 words of background.	bcs lop3	Buffer full?;;done	pla	Get rid of fore and	background colors.	pla;;	ldx <dataArea+2	Return address of pattern buffer.	lda <dataArea	clc	adc #pattern	bcc ok2	inxok2	tay;exit	pla	Get rid of stack direct page.	pla;	pld	Return caller's direct page.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;          Put word	of foreground color	into pattern buffer.;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;;   IN:    y = index into pattern buffer to store foreground color.;;  OUT:    Carry clear if pattern is now full.;setFore	lda 5,s	Get foreground color.	bra enter110;;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;          Put word	of background color	into pattern buffer.;110= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;;   IN:    y = index into pattern buffer to store background color.;;  OUT:    Carry clear if pattern is now full.;setBack	lda 3,s	Get background color.;enter110	sta [<dataArea],y	dey	dey	cpy #pattern	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;          Smear low nibble into all nibbles.;120= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;;   IN:    a = color in low nibble.;;  OUT:    a = color in all four nibbles.;getcolor	and #$000F	pha	asl a	asl a	asl a	asl a	ora 1,s	sta 1,s	xba	ora 1,s	plx	rts;	ENDP;;;===============================================================;          Push pointer to direct page location.;===============================================================;*pushRect   PRIVATEpushRect	PROC;		;using equates;;	lda #cRect	brl pushDpage	ENDP;;;===============================================================;          Push long value from control	record.;===============================================================;;   IN:    <ctlPtr = pointer to control	record.;          y = index to high word of field to push.;*pushCtlLong PRIVATEpushCtlLong	PROC;		;using equates;;	plx	Get return address.;	lda [<ctlPtr],y	pha	dey	dey	lda [<ctlPtr],y	pha;	phx	Put return address back.	rts	ENDP;;;===============================================================;          Get zoom	box's coordinates.;===============================================================;;   IN:    <ctlPtr = pointer to title bar control.;;  OUT:    <cRect = zoom box's coordinates.;*getzoomcor  PRIVATEgetzoomcor	PROC;		;using equates;;	ldy #ctlRect+x2	lda [<ctlPtr],y	sec	sbc #CLOSEL	sta <cRect+x2	sec	ldy #closeWidth	sbc [<globals],y	Less width of icon font.	sta <cRect+x1;	bra top_bottom	Compute top and bottom.;;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;          Get close box's coordinates.;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;;   IN:    <globals	= pointer to Window	Manager globals.;;  OUT:    <cRect = close box's coordinates.;	ENTRY getCloseCorgetCloseCor		;       ;	lda #CLOSEL	sta <cRect+x1	clc	ldy #closeWidth	adc [<globals],y	Add width of icon font.	sta <cRect+x2;top_bottom	lda #CLOSET	sta <cRect+y1	clc	ldy #closeHeight	adc [<globals],y	Add height of icon font.	sta <cRect+y2	rts;	ENTRY getCoordsgetCoords		;       	DC.W getCloseCor,getzoomcor;	ENDP;;;==================================================;          Smear color into all 4 nibbles.;==================================================;;   IN:    a = color in low nibble.;;  OUT:    a = color in all 4 nibbles.;*smear      PRIVATEsmear	PROC;	and #$000F	pha	asl a	asl a	asl a	asl a	ora 1,s	sta 1,s	xba	ora 1,s	plx	rts	ENDP;;;================================;          Push line size.;================================;;   IN:    <globals	= pointer to Window	Manager's global data area.;;  OUT:    PUSH:WORD - width of lines.;          PUSH:WORD - height of lines.;*pushLineSize PRIVATEpushLineSize	PROC;		;using equates;;	jsr getLineSize	a = width, x = height.;	ply	Get return address.;	pha	Push width.	phx	Push height.;	phy	Put return address back.	rts	ENDP;;;===================================;          Get size	of lines.;===================================;;   IN:    <globals	= pointer to Window	Manager's global data area.;;  OUT:    a = width of lines.;          x = height of lines.;*getLineSize PRIVATEgetLineSize	PROC;		;using equates;;	ldy #lineW	lda [<globals],y	Return width in a.	ldx #1	Return height in x.	rts	ENDP;;;=======================================================;          Get pointer to window controls control.;=======================================================;;   IN:    <ctlPtr = pointer to control.;          ctlData = pointer to window.;;  OUT:    <ctlWind = pointer to window that controls are around.;*getWindPtr PRIVATEgetWindPtr	PROC;		;using equates;;	ldy #ctlData	lda [<ctlPtr],y	sta <ctlWind	iny	iny	lda [<ctlPtr],y	sta <ctlWind+2	rts	ENDP;;========================================;          Solid color patterns.;========================================;	if 0 then		;removed 27-Sep-90 DAL	EXPORT solidColorssolidColors	PROC	EXPORT colorBlackcolorBlack    	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $00	DC.B $11	DC.B $11	DC.B $11	DC.B $11	DC.B $11	DC.B $11	DC.B $11	DC.B $11	DC.B $11	DC.B $11	DC.B $11	D