ork+2	Save.	pei <cWork;	sta <cWork+2	dey	dey	lda [<ctlWind],y	sta <cWork;	ldy #4	Unlock the title.	lda [<cWork],y	and #$7FFF	sta [<cWork],y;	plx	Restore.	stx <cWork	plx	stx <cWork+2@exit	rts	ENDP;;	END;;